#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long fastPower(long long base, int exp) {
    long long result = 1;
    long long cur = base;
    int e = exp;
    while (e > 0) {
        if (e & 1) {
            result = (result * cur) % MOD;
        }
        cur = (cur * cur) % MOD;
        e >>= 1;
    }
    return result;
}

vector<vector<long long>> multiplyMatrices(const vector<vector<long long>>& a, const vector<vector<long long>>& b) {
    int rowsA = a.size(), colsA = a[0].size();
    int rowsB = b.size(), colsB = b[0].size();
    vector<vector<long long>> res(rowsA, vector<long long>(colsB, 0));
    for (int i = 0; i < rowsA; i++) {
        for (int j = 0; j < colsB; j++) {
            long long sum = 0;
            for (int k = 0; k < colsA; k++) {
                sum += a[i][k] * b[k][j];
            }
            res[i][j] = sum % MOD;
        }
    }
    return res;
}

vector<vector<long long>> matrixFastPower(vector<vector<long long>> base, int power) {
    if (power == 1) return base;
    vector<vector<long long>> half = matrixFastPower(base, power / 2);
    vector<vector<long long>> result = multiplyMatrices(half, half);
    if (power % 2 == 1) {
        result = multiplyMatrices(result, base);
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, l, r;
    cin >> n >> m >> l >> r;

    if ((n % 2 == 1) && (m % 2 == 1)) {
        long long answer = fastPower(fastPower(r - l + 1, n), m);
        cout << answer << "\n";
        return 0;
    }

    int evenCount = r / 2 - (l + 1) / 2 + 1;
    int oddCount = (r - l + 1) - evenCount;

    vector<vector<long long>> matrix = {{evenCount, oddCount}, {oddCount, evenCount}};
    matrix = matrixFastPower(matrix, n);
    matrix = matrixFastPower(matrix, m);
    cout << matrix[0][0] << "\n";

    return 0;
}
